// Automation 1 - step 3: the email text in English, with {PLACEHOLDERS} for the numbers.
// Gemini translates this ONCE (not 50 times) -> fast and inside the free limit.
const en = {
  subject: "{MONTH} driver salaries – {STATION}",
  demo: "DEMO – this email is for {CASHIER}. PayDesk sent it to the demo inbox instead.",
  greeting: "Dear {STATION} cashier,",
  approved: "The {MONTH} driver salaries are approved and final.",
  drivers_line: "Drivers at your station: {DRIVERS}",
  cash_line: "Cash drivers (you pay): {CASH_N} – SAR {CASH_AMOUNT}",
  bank_line: "Bank drivers (bank pays): {BANK_N} – SAR {BANK_AMOUNT}",
  prepare: "Please prepare SAR {CASH_AMOUNT} in cash and pay these drivers:",
  instruction: "Pay each driver the exact amount, ask him to sign the attached sheet, and keep the signed sheet for the finance team.",
  no_cash: "You have no cash drivers this month – nothing to pay in cash.",
  bank_note: "Bank drivers will receive their salary by bank transfer. You don't pay them.",
  disputes: "Drivers can see their full payslip in PayDesk. If a driver doesn't agree with an amount, he can press \"I don't agree\" on his payslip.",
  regards: "Regards,",
  team: "Payroll team – PayDesk",
  col_id: "Driver ID",
  col_name: "Name",
  col_net: "Net to pay (SAR)",
  total: "Total",
};

const prompt =
  "Translate the VALUES of this JSON object into clear, polite Modern Standard Arabic " +
  "for a Saudi logistics company email to a station cashier. " +
  "Keep every placeholder in curly braces (like {STATION}) exactly as it is - do not translate or remove them. " +
  "Keep the words SAR and PayDesk in English. Keep the same keys. Return only the JSON object.\n\n" +
  JSON.stringify(en, null, 2);

return [{
  json: {
    en,
    request: {
      contents: [{ role: "user", parts: [{ text: prompt }] }],
      generationConfig: { temperature: 0.2, responseMimeType: "application/json" },
    },
  },
}];

// Automation 1 - step 5: build one English + Arabic email for every station.
const data = $('Get station emails').first().json;
const en = $('Prepare Arabic request').first().json.en;

// Read Gemini's Arabic. If anything is wrong, send English only (the email still goes out).
let ar = null;
try {
  const g = $input.first().json;
  const text = g.candidates[0].content.parts[0].text.replace(/```json|```/g, "").trim();
  const obj = JSON.parse(text);
  for (const k of Object.keys(en)) {
    const need = en[k].match(/\{[A-Z_]+\}/g) || [];
    if (typeof obj[k] !== "string" || !need.every((p) => obj[k].includes(p))) throw new Error("bad key " + k);
  }
  ar = obj;
} catch (e) {
  ar = null;
}

const money = (x) => Number(x).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

function fill(t, st) {
  return esc(t)
    .replaceAll("{STATION}", esc(`${st.station_code} ${st.station}`))
    .replaceAll("{MONTH}", esc(data.month_name))
    .replaceAll("{CASHIER}", esc(st.cashier_email))
    .replaceAll("{DRIVERS}", st.drivers)
    .replaceAll("{CASH_N}", st.cash_drivers)
    .replaceAll("{CASH_AMOUNT}", money(st.cash_total))
    .replaceAll("{BANK_N}", st.bank_drivers)
    .replaceAll("{BANK_AMOUNT}", money(st.bank_total));
}

const cell = "padding:6px 10px;border:1px solid #cbd5e1;";

function section(L, st, rtl) {
  const align = rtl ? "right" : "left";
  const end = rtl ? "left" : "right";
  let h = `<div dir="${rtl ? "rtl" : "ltr"}" ${rtl ? 'lang="ar"' : ""} style="text-align:${align};font-family:${rtl ? "Tahoma," : ""}Arial,sans-serif;font-size:14px;color:#1e293b;line-height:1.6">`;
  h += `<p>${fill(L.greeting, st)}</p><p><b>${fill(L.approved, st)}</b></p>`;
  h += `<ul style="padding-${align}:20px"><li>${fill(L.drivers_line, st)}</li><li>${fill(L.cash_line, st)}</li><li>${fill(L.bank_line, st)}</li></ul>`;
  if (st.cash_list.length) {
    h += `<p>${fill(L.prepare, st)}</p>`;
    h += `<table style="border-collapse:collapse;font-size:13px"><tr style="background:#e0e7ff">`;
    h += `<th style="${cell}">#</th><th style="${cell}">${fill(L.col_id, st)}</th><th style="${cell}">${fill(L.col_name, st)}</th><th style="${cell}text-align:${end}">${fill(L.col_net, st)}</th></tr>`;
    st.cash_list.forEach((d, i) => {
      h += `<tr><td style="${cell}">${i + 1}</td><td style="${cell}">${esc(d.driver_id)}</td><td style="${cell}" dir="ltr">${esc(d.name)}</td><td style="${cell}text-align:${end}">${money(d.net)}</td></tr>`;
    });
    h += `<tr style="font-weight:bold"><td style="${cell}" colspan="3">${fill(L.total, st)}</td><td style="${cell}text-align:${end}">${money(st.cash_total)}</td></tr></table>`;
    h += `<p>${fill(L.instruction, st)}</p>`;
  } else {
    h += `<p>${fill(L.no_cash, st)}</p>`;
  }
  if (st.bank_drivers) h += `<p>${fill(L.bank_note, st)}</p>`;
  h += `<p>${fill(L.disputes, st)}</p><p>${fill(L.regards, st)}<br>${fill(L.team, st)}</p></div>`;
  return h;
}

return data.stations.map((st) => {
  let html = `<div style="max-width:720px">`;
  html += `<p style="background:#fef3c7;color:#92400e;padding:8px 12px;border-radius:6px;font-family:Arial,sans-serif;font-size:12px">${fill(en.demo, st)}</p>`;
  html += section(en, st, false);
  if (ar) html += `<hr style="margin:24px 0;border:none;border-top:1px solid #e2e8f0">` + section(ar, st, true);
  html += `</div>`;
  const subject = st.subject + (ar ? " | " + fill(ar.subject, st).replace(/&amp;/g, "&") : "");
  return {
    json: {
      email_id: st.email_id, period: data.period, month_name: data.month_name,
      station_code: st.station_code, station: st.station, cashier_email: st.cashier_email,
      send_to: st.send_to, subject, html, arabic: !!ar,
      drivers: st.drivers, cash_drivers: st.cash_drivers, cash_total: st.cash_total,
      bank_drivers: st.bank_drivers, bank_total: st.bank_total,
    },
  };
});

// Automation 1 - step 8: did Gmail send it? Make one log row for this station.
const b = $('Build emails').item.json;
const r = $json;
const ok = !r.error && !!r.id;
return {
  json: {
    time: new Date().toISOString(),
    period: b.period,
    station_code: b.station_code,
    station: b.station,
    cashier_email: b.cashier_email,
    sent_to: b.send_to,
    drivers: b.drivers,
    cash_drivers: b.cash_drivers,
    cash_total: b.cash_total,
    bank_drivers: b.bank_drivers,
    bank_total: b.bank_total,
    arabic: b.arabic ? "yes" : "no",
    status: ok ? "sent" : "failed",
    gmail_id: ok ? r.id : "",
    error: ok ? "" : String(r.error?.message ?? r.error ?? "unknown error"),
    email_id: b.email_id,
  },
};
